class Account {
    private final String accountId;
    private final String cardNumber;
    private final String hashedPin;
    private long balance;       // in smallest currency unit
    private boolean isLocked;
    private int failedAttempts;
    private static final int MAX_ATTEMPTS = 3;

    public boolean verifyPin(String pin) {
        if (isLocked)
            throw new AccountLockedException(accountId);

        if (hashPin(pin).equals(hashedPin)) {
            failedAttempts = 0;  // reset on success
            return true;
        }

        failedAttempts++;
        if (failedAttempts >= MAX_ATTEMPTS) {
            isLocked = true;
            throw new AccountLockedException(
                "Account locked after " + MAX_ATTEMPTS + " failed attempts");
        }
        return false;
    }

    // synchronized: two ATMs might debit the same account
    public synchronized void debit(long amount) {
        if (amount <= 0)
            throw new InvalidAmountException("Amount must be positive");
        if (amount > balance)
            throw new InsufficientBalanceException(
                "Need " + amount + ", have " + balance);
        balance -= amount;
    }

    public synchronized void credit(long amount) {
        if (amount <= 0)
            throw new InvalidAmountException("Amount must be positive");
        balance += amount;
    }

    public synchronized long getBalance() { return balance; }
    public boolean isLocked() { return isLocked; }

    private String hashPin(String pin) {
        // In production: bcrypt/scrypt. Here: simplified.
        return Integer.toHexString(pin.hashCode());
    }
}

class CashDispenser {
    private final int denomination;
    private int count;
    private CashDispenser nextHandler;

    public CashDispenser(int denomination, int count) {
        this.denomination = denomination;
        this.count = count;
    }

    public void setNext(CashDispenser next) { this.nextHandler = next; }

    // ── dispense (Chain of Responsibility) ──
    // Returns denomination → number of bills dispensed
    public Map<Integer, Integer> dispense(int amount) {
        Map<Integer, Integer> result = new LinkedHashMap<>();

        int billsNeeded = amount / denomination;
        int billsToUse  = Math.min(billsNeeded, count);

        if (billsToUse > 0) {
            result.put(denomination, billsToUse);
            count -= billsToUse;
            amount -= billsToUse * denomination;
        }

        if (amount > 0) {
            if (nextHandler != null) {
                result.putAll(nextHandler.dispense(amount));
            } else {
                // End of chain, still have remainder
                // Rollback: put bills back
                if (billsToUse > 0) count += billsToUse;
                throw new ATMInsufficientCashException(
                    "Cannot dispense remaining: " + amount);
            }
        }
        return result;
    }

    // Pre-check without actually dispensing
    public boolean canDispense(int amount) {
        int use = Math.min(amount / denomination, count);
        int remainder = amount - use * denomination;
        if (remainder == 0) return true;
        return nextHandler != null && nextHandler.canDispense(remainder);
    }

    public void refill(int qty) { this.count += qty; }

    // ── Build chain (static factory) ────────
    public static CashDispenser buildChain(
            int[] denominations, int[] counts) {
        CashDispenser head = null, prev = null;
        for (int i = 0; i < denominations.length; i++) {
            CashDispenser handler =
                new CashDispenser(denominations[i], counts[i]);
            if (head == null) head = handler;
            if (prev != null) prev.setNext(handler);
            prev = handler;
        }
        return head;
    }
}

enum ATMState { IDLE, CARD_INSERTED, AUTHENTICATED }

class ATM {
    private final String atmId;
    private final CashDispenser dispenserChain;
    private final AccountRepository accountRepo;
    private ATMState state = ATMState.IDLE;
    private Account currentAccount;

    public ATM(String atmId, AccountRepository repo,
               int[] denominations, int[] counts) {
        this.atmId = atmId;
        this.accountRepo = repo;
        this.dispenserChain = CashDispenser.buildChain(
            denominations, counts);
    }

    // ── Session management ──────────────────
    public void insertCard(String cardNumber) {
        if (state != ATMState.IDLE)
            throw new InvalidStateException("Card already inserted");
        currentAccount = accountRepo.findByCard(cardNumber);
        if (currentAccount == null)
            throw new InvalidCardException(cardNumber);
        state = ATMState.CARD_INSERTED;
    }

    public boolean enterPin(String pin) {
        requireState(ATMState.CARD_INSERTED);
        boolean ok = currentAccount.verifyPin(pin);
        if (ok) state = ATMState.AUTHENTICATED;
        return ok;
    }

    // ── Operations (require AUTHENTICATED) ──
    public long checkBalance() {
        requireState(ATMState.AUTHENTICATED);
        return currentAccount.getBalance();
    }

    public Map<Integer, Integer> withdraw(int amount) {
        requireState(ATMState.AUTHENTICATED);

        if (amount <= 0 || amount % 100 != 0)
            throw new InvalidAmountException(
                "Amount must be positive multiple of 100");

        // Pre-check dispensability
        if (!dispenserChain.canDispense(amount))
            throw new ATMInsufficientCashException(
                "ATM cannot dispense " + amount);

        // Debit account first (will throw if insufficient)
        currentAccount.debit(amount);

        // Dispense bills
        try {
            return dispenserChain.dispense(amount);
        } catch (ATMInsufficientCashException e) {
            // Compensating transaction: credit back
            currentAccount.credit(amount);
            throw e;
        }
    }

    public void deposit(int amount) {
        requireState(ATMState.AUTHENTICATED);
        if (amount <= 0)
            throw new InvalidAmountException("Amount must be positive");
        currentAccount.credit(amount);
    }

    public void transfer(String targetAccountId, long amount) {
        requireState(ATMState.AUTHENTICATED);
        if (amount <= 0)
            throw new InvalidAmountException("Amount must be positive");

        Account target = accountRepo.findById(targetAccountId);
        if (target == null)
            throw new AccountNotFoundException(targetAccountId);

        // Lock ordering: always lock lower accountId first
        // to prevent deadlock between two concurrent transfers
        Account first, second;
        if (currentAccount.getAccountId()
                .compareTo(target.getAccountId()) < 0) {
            first = currentAccount; second = target;
        } else {
            first = target; second = currentAccount;
        }

        synchronized (first) {
            synchronized (second) {
                currentAccount.debit(amount);
                target.credit(amount);
            }
        }
    }

    public void ejectCard() {
        currentAccount = null;
        state = ATMState.IDLE;
    }

    private void requireState(ATMState required) {
        if (state != required)
            throw new InvalidStateException(
                "Expected " + required + ", at " + state);
    }
}
